class Money:
    def __init__(self, cents):
        self.cents = int(cents)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents

    def __hash__(self):
        return hash(self.cents)

    def __repr__(self):
        return f'Money({self.cents})'

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents + other.cents)

    def __radd__(self, other):
        if other == 0:
            return self
        return NotImplemented

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents - other.cents)

    def __neg__(self):
        return Money(-self.cents)

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        dollars, cents = divmod(abs(self.cents), 100)
        return f'{sign}${dollars:,}.{cents:02d}'

    def split(self, n):
        """Split into n parts whose cents sum to the original amount.

        The remainder is spread one cent at a time over the first parts.
        """
        if n <= 0:
            raise ValueError('n must be positive')
        base, remainder = divmod(self.cents, n)
        return [Money(base + 1 if i < remainder else base) for i in range(n)]
